namespace EnterpriseDocumentIntelligence.BuildingBlocks.Domain;
public sealed class OutboxMessage{public Guid Id{get;private set;}=Guid.NewGuid();public string Topic{get;private set;}=null!;public string Payload{get;private set;}=null!;public string CorrelationId{get;private set;}=null!;public DateTimeOffset OccurredAt{get;private set;}=DateTimeOffset.UtcNow;public DateTimeOffset? PublishedAt{get;private set;}public int Attempts{get;private set;}public string? LastError{get;private set;}private OutboxMessage(){}public OutboxMessage(string topic,string payload,string correlationId){if(string.IsNullOrWhiteSpace(topic))throw new ArgumentException("Topic is required",nameof(topic));if(string.IsNullOrWhiteSpace(payload))throw new ArgumentException("Payload is required",nameof(payload));Topic=topic;Payload=payload;CorrelationId=correlationId??throw new ArgumentNullException(nameof(correlationId));}public void MarkAttempt(string? error=null){Attempts++;LastError=error;}public void MarkPublished()=>PublishedAt=DateTimeOffset.UtcNow;public bool IsPublished=>PublishedAt.HasValue;}